DO $$ DECLARE def text;BEGIN SELECT pg_get_functiondef('public.capitalize_bill_allocation(uuid)'::regprocedure) INTO def;IF position('-- Idempotency: already posted' IN def)>0 THEN RAISE EXCEPTION 'Unexpected asset source function';END IF;IF position('IF NOT a.capitalize THEN' IN def)=0 THEN RAISE EXCEPTION 'Asset guard anchor unavailable';END IF;def:=replace(def,'IF NOT a.capitalize THEN','IF NOT public.finance_schedule_manager(a.tenant_id) THEN RAISE EXCEPTION ''Owner or admin required'';END IF;IF NOT EXISTS(SELECT 1 FROM public.expense_bills WHERE tenant_id=a.tenant_id AND id=a.bill_id AND approval_status IN(''draft'',''pending_review'',''approved'')) THEN RAISE EXCEPTION ''Unposted source bill required'';END IF; IF NOT a.capitalize THEN');def:=replace(def,'ELSE a.account_id','ELSE (SELECT id FROM chart_of_accounts WHERE tenant_id=a.tenant_id AND code=''1500'' AND account_type=''asset'' AND is_active)');EXECUTE def;END $$;